    if v < 0:
        return f"- {-v}"
    return f"+ {v}"

def power(c, n, x0):
    print(f"  ({c}x^{n})' = {c * n}x^{n - 1}, by the power rule")
    print(f"  at x = {x0}: {c * n} * ({x0})^{n - 1} = {c * n * x0 ** (n - 1)}")

def product(a1, b1, a2, b2, x0):
    f, g = a1 * x0 + b1, a2 * x0 + b2
    print(f"  f = {a1}x {signed(b1)}, g = {a2}x {signed(b2)}: f = {f}, g = {g}, f' = {a1}, g' = {a2}")
    print(f"  (fg)' = f'g + fg' = ({a1})({g}) + ({f})({a2}) = {a1 * g + f * a2}")

def quotient(c2, c1, c0, a, b, x0):
    f = c2 * x0**2 + c1 * x0 + c0
    df = 2 * c2 * x0 + c1
    g = a * x0 + b
    if g == 0:
        print(f"  g({x0}) = 0, so neither f/g nor its derivative exists there")
        return
    top = df * g - f * a
    print(f"  f = {f}, f' = {df}, g = {g}, g' = {a}")
    print(f"  (f/g)' = (f'g - fg')/g^2 = (({df})({g}) - ({f})({a}))/({g})^2 = {top / (g * g)}")

def chain(a, b, n, x0):
    u0 = a * x0 + b
    outer = n * u0 ** (n - 1)
    print(f"  inside u = {a}x {signed(b)} = {u0}, outside u^{n}")
    print(f"  slope = {n}u^{n - 1} * u' = ({outer})({a}) = {outer * a}")

