    if x0 * x0 + y0 * y0 != R:
        print(f"  ({x0}, {y0}) is not on x^2 + y^2 = {R}")
    elif y0 == 0:
        print("  2x + 2y y' = 0 with y = 0: a vertical tangent")
    else:
        print(f"  2x + 2y y' = 0, so y' = -x/y = {-x0 / y0}")

