    return f"+ {v}"

def tangent(c3, c2, c1, c0, a):
    fa = c3 * a**3 + c2 * a**2 + c1 * a + c0
    slope = 3 * c3 * a**2 + 2 * c2 * a + c1
    print(f"  f({a}) = {fa}, f'({a}) = {slope}")
    print(f"  y = {fa} + ({slope})(x {signed(-a)}), which is y = {slope}x {signed(fa - slope * a)}")

def implicit(x0, y0):
    c = x0 * x0 + x0 * y0 + y0 * y0
    print(f"  the curve through ({x0}, {y0}): x^2 + xy + y^2 = {c}")
    if x0 + 2 * y0 == 0:
        print("  x + 2y = 0, so the tangent is vertical")
    else:
        print(f"  y' = -(2x + y)/(x + 2y) = {-(2 * x0 + y0) / (x0 + 2 * y0)}")

def inverse(p, b):
    found = False
    for a in range(-10, 11):
        if a**3 + p * a == b:
            found = True
            slope = 3 * a * a + p
            print(f"  f({a}) = {b}, and f'({a}) = {slope}")
            if slope == 0:
                print("  f' = 0 there, so the inverse has a vertical tangent")
            else:
                print(f"  (f^-1)'({b}) = 1/f'({a}) = {Fraction(1, slope)}")
