        tangent(nums[0], nums[1], nums[2], nums[3], nums[4])
    elif kind == "implicit":
        implicit(nums[0], nums[1])
    elif kind == "inverse":
        inverse(nums[0], nums[1])
    else:
        logdiff(nums[0], nums[1], nums[2])

