    ("tangent", [1, 0, -12, 1, 2]), ("implicit", [2, 3]), ("inverse", [2, 3]),
    ("logdiff", [2, 0, 1]), ("tangent", [0, 1, 0, 0, -3]), ("implicit", [-2, 1]),
    ("inverse", [0, 0]), ("logdiff", [1, 0, 2.5]),
]
for i in range(len(problems)):
