import math
from fractions import Fraction

def ladder(L, x, dxdt):
    if x >= L:
        print("  the bottom can't be that far from the wall")
        return
    y = math.sqrt(L * L - x * x)
    print(f"  x^2 + y^2 = {L * L}, so y = sqrt({L * L} - {x * x}) = {y:.4f}")
    print(f"  2x x' + 2y y' = 0, so y' = -x x'/y = {-x * dxdt / y:.4f}")

def balloon(dVdt, d):
    r = d / 2
    drdt = dVdt / (4 * math.pi * r * r)
    print(f"  r = {r}, V = (4/3) pi r^3, so V' = 4 pi r^2 r'")
    print(f"  r' = {dVdt}/(4 pi ({r})^2) = {drdt:.4f}, S' = 8 pi r r' = {8 * math.pi * r * drdt:.4f}")

def motion(b, c, t):
    v = 3 * t * t + 2 * b * t + c
    a = 6 * t + 2 * b
    print(f"  v = 3t^2 + 2bt + c = {v}, a = 6t + 2b = {a}")
    if v == 0:
        print("  v = 0: stopped for an instant")
        return
    if v > 0:
        way = "forward"
    else:
        way = "backward"
    if a == 0:
        print(f"  moving {way}, neither speeding up nor slowing down")
    elif v * a > 0:
        print(f"  moving {way} and speeding up, since v and a share a sign")
    else:
        print(f"  moving {way} and slowing down, since v and a have opposite signs")

def growth(N0, k, t):
    N = N0 * math.exp(k * t)
    print(f"  N({t}) = {N0} e^({k} * {t}) = {N:.2f}")
    print(f"  N' = {k} N = {k * N:.2f}")

def run(kind, nums):
    if kind == "ladder":
        ladder(nums[0], nums[1], nums[2])
    elif kind == "balloon":
        balloon(nums[0], nums[1])
    elif kind == "motion":
        motion(nums[0], nums[1], nums[2])
    else:
        growth(nums[0], nums[1], nums[2])

