    ("growth", [800, Fraction(3, 10), 4]), ("ladder", [10, 10, 1]), ("balloon", [-10, 20]),
    ("motion", [-6, 9, 3]), ("motion", [-6, 9, 2]),
]
for i in range(len(problems)):
    kind, nums = problems[i]
    nums = [Fraction(v) for v in nums]
    text = ""
    for v in nums:
        text = text + f" {v}"
    print(f"Problem {i + 1}: {kind}{text}")
    run(kind, nums)

