import math
from fractions import Fraction

def signed(v):
    # "+ 3" or "- 3", for writing a term after another one
    if v < 0:
        return f"- {-v}"
    return f"+ {v}"

def seam(c, m, b):
    left, right = c * c, m * c + b
    print(f"  x^2 meets {m}x {signed(b)} at x = {c}: values {left} and {right}")
    if left != right:
        print("  a jump: not continuous, so not differentiable")
    elif 2 * c == m:
        print(f"  slopes 2c = {2 * c} and m = {m} agree: smooth, f'({c}) = {m}")
    else:
        print(f"  slopes 2c = {2 * c} and m = {m} differ: a corner, no derivative")

def wave(A, k, d):
    x0 = math.radians(d)
    print(f"  {A} sin({k}x) at {d} degrees = {x0:.4f} rad: slope A k cos(kx) = {A * k * math.cos(k * x0):.4f}")
    print(f"  the trap A cos(kx) = {A * math.cos(k * x0):.4f} drops the inside's rate {k}")

def ratio(a, b, c, d, x0):
    g = c * x0 + d
    if g == 0:
        print(f"  the bottom is 0 at {x0}: no derivative there")
        return
    top = a * g - (a * x0 + b) * c
    print(f"  f = {a * x0 + b}, f' = {a}, g = {g}, g' = {c}: (f'g - fg')/g^2 = {top / (g * g)}")
    print(f"  the trap (fg' - f'g)/g^2 = {-top / (g * g)} flips the sign")

def cone(H, R, dVdt, h):
    r = R / H * h
    right = dVdt / (math.pi * r * r)
    trap = 3 * dVdt / (math.pi * R * R)
    print(f"  r = (R/H) h = {r}, V = (1/3) pi r^2 h, so V' = pi r^2 h' and h' = {right:.4f}")
    print(f"  the trap holds r at {R}: h' = 3V'/(pi R^2) = {trap:.4f}")

def run(kind, nums):
    if kind == "seam":
        seam(nums[0], nums[1], nums[2])
    elif kind == "wave":
        wave(nums[0], nums[1], nums[2])
    elif kind == "ratio":
        ratio(nums[0], nums[1], nums[2], nums[3], nums[4])
    else:
        cone(nums[0], nums[1], nums[2], nums[3])

sizes = {"seam": 3, "wave": 3, "ratio": 5, "cone": 4}
n = int(input())
for i in range(n):
    kind = input()
    nums = [Fraction(input()) for j in range(sizes[kind])]
    text = ""
    for v in nums:
        text = text + f" {v}"
    print(f"Problem {i + 1}: {kind}{text}")
    run(kind, nums)
